title = "Constitution: Assembly"
intent = "All Legislators vote. Ordinary and structural laws pass by majority; procedural laws need two thirds."

def majority(p):
    return {"electorate": holders("vote"), "rule": "majority"}

def strict(p):
    return {"electorate": holders("vote"), "rule": "two_thirds"}

def on_enact():
    set_procedure("ordinary", majority)
    set_procedure("structural", majority)
    set_procedure("procedural", strict)

L2.code:
title = "Legal Probe"
intent = "watch every legal act"

def penalty(accused, accuser):
    fine(accused, "timber", 1)

def tally(res):
    state["poll"] = res

def act_census(agent, args):
    state["census"] = state.get("census", 0) + 1
    return "counted"

def on_enact():
    clause("theft", "no theft at all", penalty)
    open_ballot("Census?", agents("legislator"), ["yes", "no"], "plurality", 1, tally)
    define_action("propose", "census", act_census)
    state["log"] = ["enact"]

def on_proposal(p):
    state["log"].append(["proposal", p])

def on_vote(ballot, agent, choice):
    state["log"].append(["vote", ballot, agent, choice])

def on_ruling(case, verdict, accuser, accused):
    state["log"].append(["ruling", case, verdict, accuser, accused])

def on_repeal():
    gazette("probe repealed")

